// Sleepy Blob toggle: A clay blob yawns, stretches its tiny arms and wakes up. Switch it off and it nods back to sleep.
// One file, no dependencies. From https://zerowing.in/toggles/
//
// Use it:
//   <script type="module" src="blob.js"></script>
//
//   <tg-blob style="display:block; width:360px; height:220px"></tg-blob>
//
//   <script type="module">
//     const t = document.querySelector("tg-blob");
//     t.addEventListener("change", (e) => console.log("on?", e.detail.checked));
//     // t.checked = true;  t.toggle();
//   </script>
//
// API: the `checked` attribute / .checked property, .toggle(), a "change" event ({detail: {checked}}).
// The switch scales to fit its box (designed at 360x220); fill="0.9" sets how much of the box it fills (default 0.82).
// The element paints its own scene background, so give it a rounded container if you want one.

// ---- shared base ----
// Shared base for every toggle in the library.
//
// Contract (every components/<id>.js follows it):
//   - `export default class extends ToggleBase` and `customElements.define('tg-<id>', …)` at the bottom.
//   - Override `template()` → HTML string for the shadow root (include its own <style>).
//     Everything is drawn inside a fixed design stage of W×H px (static W/H, default 360×220);
//     the base scales that stage to fit the host. The host itself is the full scene (paint
//     :host's background yourself if the style swaps day/night etc.).
//   - Override `render(on, instant)` → apply the on/off state. `instant` is true on first paint.
//   - Optional `tick(t, dt)` → called every animation frame while connected (t in ms, from
//     performance.now(), so a virtual clock can drive it). Return nothing.
//   - Any element with [data-hit] is the clickable switch; clicking it calls this.toggle().
//   - Time sources: only performance.now() / rAF / CSS transitions & animations. No setTimeout
//     chains for visible motion (capture seeks a virtual clock).
//
// Public API on every element: .checked (bool, reflects the `checked` attribute), .toggle(),
// 'change' event with detail {checked}. this.scale = current stage scale, this.dpr = devicePixelRatio.

class ToggleBase extends HTMLElement {
  static W = 360;
  static H = 220;
  static observedAttributes = ['checked'];

  constructor() {
    super();
    this.root = this.attachShadow({ mode: 'open' });
    this.scale = 1;
    this.dpr = Math.min(window.devicePixelRatio || 1, 2);
    this._raf = 0;
    this._last = 0;
  }

  template() { return ''; }
  render(_on, _instant) {}
  tick(_t, _dt) {}
  onResize() {}

  connectedCallback() {
    if (!this._built) {
      const { W, H } = this.constructor;
      this.root.innerHTML = `
        <style>
          :host { display: block; position: relative; overflow: hidden; contain: content; -webkit-tap-highlight-color: transparent; }
          .tg-stage { position: absolute; left: 50%; top: 50%; width: ${W}px; height: ${H}px;
            transform: translate(-50%, -50%) scale(var(--s, 1)); transform-origin: 50% 50%; }
          [data-hit] { cursor: pointer; }
        </style>
        <div class="tg-stage">${this.template()}</div>`;
      this.stage = this.root.querySelector('.tg-stage');
      this.root.addEventListener('click', (e) => {
        if (e.composedPath().some((n) => n instanceof Element && n.hasAttribute('data-hit'))) this.toggle();
      });
      this._built = true;
      this.setup?.();
      this.render(this.checked, true);
    }
    this._ro = new ResizeObserver(() => this._fit());
    this._ro.observe(this);
    this._fit();
    const loop = (t) => {
      const dt = this._last ? Math.min(t - this._last, 64) : 16;
      this._last = t;
      this.tick(t, dt);
      this._raf = requestAnimationFrame(loop);
    };
    this._raf = requestAnimationFrame(loop);
  }

  disconnectedCallback() {
    cancelAnimationFrame(this._raf);
    this._ro?.disconnect();
    this._last = 0;
  }

  _fit() {
    const { W, H } = this.constructor;
    const r = this.getBoundingClientRect();
    if (!r.width || !r.height) return;
    // Toggle fills ~78% of the shorter fit so every tile has breathing room.
    this.scale = Math.min(r.width / W, r.height / H) * (parseFloat(this.getAttribute('fill')) || 0.82);
    this.style.setProperty('--s', this.scale);
    this.onResize();
  }

  get checked() { return this.hasAttribute('checked'); }
  set checked(v) { this.toggleAttribute('checked', !!v); }

  attributeChangedCallback(name, oldV, newV) {
    if (name === 'checked' && this._built && (oldV === null) !== (newV === null)) {
      this.render(this.checked, false);
      this.dispatchEvent(new CustomEvent('change', { detail: { checked: this.checked }, bubbles: true }));
    }
  }

  toggle() { this.checked = !this.checked; }

  $(sel) { return this.root.querySelector(sel); }
  $$(sel) { return [...this.root.querySelectorAll(sel)]; }

  // Size a <canvas> to cover `w×h` design px at full device resolution.
  sizeCanvas(cv, w, h) {
    const k = this.scale * this.dpr;
    cv.width = Math.max(1, Math.round(w * k));
    cv.height = Math.max(1, Math.round(h * k));
    cv.style.width = w + 'px';
    cv.style.height = h + 'px';
    const ctx = cv.getContext('2d');
    ctx.setTransform(k, 0, 0, k, 0, 0);
    return ctx;
  }
}

// Easing helpers shared by components.
const ease = {
  outCubic: (x) => 1 - Math.pow(1 - x, 3),
  inOutCubic: (x) => (x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2),
  outBack: (x, s = 1.70158) => 1 + (s + 1) * Math.pow(x - 1, 3) + s * Math.pow(x - 1, 2),
  // Critically-damped-ish spring step: returns new [pos, vel].
  spring: (pos, vel, target, dt, k = 170, d = 18) => {
    const s = dt / 1000;
    const a = -k * (pos - target) - d * vel;
    vel += a * s;
    pos += vel * s;
    return [pos, vel];
  },
};

const clamp = (v, a = 0, b = 1) => Math.min(b, Math.max(a, v));
const lerp = (a, b, t) => a + (b - a) * t;

// ---- Sleepy Blob ----
// Sleepy Blob — a clay creature asleep in a clay track.
// ON  (groggy wake-up): one droopy eye opens → it waddles sleepily to the middle → BIG yawn-and-stretch
//     (tall body, stubby arms reaching up, wide O mouth, a tear) → snaps awake (eyes pop, blush) → excited hop right.
// OFF (dozing off): smile fades, lids droop → drifts to the middle → nods off twice, eyes fluttering, first "z"
//     → drifts home and falls asleep.
// One timeline position `s` (0 = asleep/left, 1 = awake/right) runs at 1/DUR per ms toward the target, so a
// click mid-act just turns the timeline around; poses are smoothed so switching acts never pops.

// Library-standard geometry (matches Snow Globe): bezel 330×160 at (15,30), window 300×130 inset 15, body Ø112.
const OFF_X = 95, ON_X = 265, MID_X = 180; // knob centre (design px)
const CY = 110;
const DUR = 2000;   // ms, both directions
const LAND = 1880;  // ON: hop touches down

const sm = (a, b, x) => { const t = clamp((x - a) / (b - a)); return t * t * (3 - 2 * t); };
const bell = (a, b, x) => (x <= a || x >= b ? 0 : Math.sin(Math.PI * (x - a) / (b - a)));
const inOutSine = (x) => -(Math.cos(Math.PI * clamp(x)) - 1) / 2;
const mix3 = (a, b, c, t) => (t < 0.5 ? a.map((v, i) => lerp(v, b[i], t * 2)) : b.map((v, i) => lerp(v, c[i], t * 2 - 1)));
const LILAC = [195, 176, 230], DAWN = [242, 176, 206], PEACH = [255, 190, 157];

const FIELDS = ['x', 'y', 'sx', 'sy', 'rot', 'lidL', 'lidR', 'droop', 'squeeze', 'mouthO', 'smile', 'cheek', 'arms', 'armUp', 'tear', 'zz', 'lookX', 'lookY'];

function poseOn(u) {
  const p = { x: OFF_X, y: 0, sx: 1, sy: 1, rot: 0, lidL: 0, lidR: 0, droop: 0, squeeze: 0, mouthO: 0, smile: 0, cheek: 0,
    arms: 0, armUp: 0, tear: 0, zz: 1 - sm(0, 260, u), lookX: 0, lookY: 1.5 };
  // 1. half-wake: one droopy eye
  const wake = sm(0, 180, u) * (1 - sm(640, 760, u));
  p.lidL = 0.42 * wake; p.droop = wake; p.lookY = 1.5 - wake * 0.5;
  // 2. sleepy waddle to the middle
  if (u >= 150) {
    const w = clamp((u - 150) / 500);
    p.x = lerp(OFF_X, MID_X, inOutSine(w));
    const step = Math.sin(w * Math.PI * 4);
    p.rot = step * 8 * (1 - sm(0.8, 1, w));
    p.y = -Math.abs(step) * 5 * (1 - sm(0.85, 1, w));
    p.sx = 1 + Math.abs(Math.cos(w * Math.PI * 4)) * 0.05 * (1 - w);
    p.sy = 1 - Math.abs(Math.cos(w * Math.PI * 4)) * 0.05 * (1 - w);
  }
  // 3. the big yawn-and-stretch
  const st = sm(660, 940, u) * (1 - sm(1300, 1460, u));
  if (u >= 650) {
    p.x = MID_X;
    const over = bell(860, 1060, u) * 0.06; // little overshoot at the top of the stretch
    p.sx = 1 - 0.15 * st - over * 0.5;
    p.sy = 1 + 0.3 * st + over;
    p.rot = Math.sin(u / 45) * 1.8 * st; // shiver of a real stretch
    p.arms = sm(680, 860, u) * (1 - sm(1380, 1500, u));
    p.armUp = st;
    p.mouthO = st;
    p.squeeze = st;
    p.tear = bell(980, 1460, u);
    p.lookY = -1.5 * st;
  }
  // 4. snap awake + 5. excited hop
  if (u >= 1440) {
    const snap = sm(1440, 1520, u);
    p.lidL = p.lidR = lerp(0, 1, snap) + bell(1440, 1600, u) * 0.3; // pop
    p.droop = 0;
    p.cheek = sm(1460, 1640, u);
    p.smile = sm(1480, 1620, u) * (1 - p.mouthO);
    p.lookX = 1.2 * snap; p.lookY = 0;
    const ant = bell(1460, 1540, u);          // anticipation squash
    p.sx += ant * 0.14; p.sy -= ant * 0.15;
  }
  if (u >= 1520) {
    const h = clamp((u - 1520) / (LAND - 1520));
    p.x = lerp(MID_X, ON_X, inOutSine(h));
    p.y = -Math.sin(Math.PI * h) * 54;
    const fly = Math.sin(Math.PI * h);
    p.sx = 1 - fly * 0.1; p.sy = 1 + fly * 0.13;
    p.rot = Math.sin(Math.PI * h) * 10;
    if (u >= LAND) {
      const l = clamp((u - LAND) / (DUR - LAND));
      p.x = ON_X; p.y = 0; p.rot = 0;
      const sq = Math.sin(Math.PI * Math.min(1, l * 1.4)) * (1 - l * 0.4);
      p.sx = 1 + sq * 0.16; p.sy = 1 - sq * 0.16;
    }
  }
  return p;
}

function poseOff(v) {
  const p = { x: ON_X, y: 0, sx: 1, sy: 1, rot: 0, lidL: 1, lidR: 1, droop: 0, squeeze: 0, mouthO: 0, smile: 1, cheek: 1,
    arms: 0, armUp: 0, tear: 0, zz: 0, lookX: 1.2, lookY: 0 };
  // 1. getting drowsy: smile fades, lids droop, slow drift to the middle
  const dz = sm(0, 320, v);
  p.smile = 1 - dz; p.cheek = 1 - dz * 0.7; p.lidL = p.lidR = lerp(1, 0.48, dz); p.droop = dz;
  p.sy = 1 - dz * 0.04; p.sx = 1 + dz * 0.03; p.lookX = 1.2 * (1 - dz); p.lookY = dz * 1.2;
  const d = clamp(v / 720);
  p.x = lerp(ON_X, MID_X, inOutSine(d));
  p.rot = -Math.sin(d * Math.PI * 2) * 4 * (1 - d);
  // 2. nodding off in the middle: two nods, eyes fluttering in between
  if (v >= 720) {
    p.x = MID_X;
    const n = bell(780, 1010, v) + bell(1110, 1380, v) * 1.15;
    p.rot = n * 13;
    p.y = n * 6;
    p.sy = 0.96 - n * 0.05; p.sx = 1.03 + n * 0.04;
    const flutter = 0.36 + 0.14 * Math.sin(v / 38);
    const lid = Math.max(0, flutter * (1 - Math.min(1, n * 2.2)) * (1 - sm(1380, 1500, v)));
    p.lidL = p.lidR = lid;
    p.cheek = 0.3 * (1 - sm(900, 1450, v));
    p.lookY = 1.5;
  }
  // 3. drift home, fully asleep
  if (v >= 1450) {
    const h = clamp((v - 1450) / (DUR - 1450));
    p.x = lerp(MID_X, OFF_X, inOutSine(h));
    p.lidL = p.lidR = 0; p.droop = 0;
    p.rot = -Math.sin(h * Math.PI) * 5;
    p.sy = lerp(0.96, 1, h); p.sx = lerp(1.03, 1, h);
    p.zz = sm(1700, 2000, v);
  }
  return p;
}

export default class Blob extends ToggleBase {
  static W = 360;
  static H = 220;

  template() {
    return `
<style>
