  .bz { background: linear-gradient(180deg, #f6effc, #e6daf6 60%, #d9caee);
    box-shadow: 0 26px 44px -20px rgba(90,60,140,.45), 0 8px 16px -8px rgba(90,60,140,.3),
      inset 0 2px 1px rgba(255,255,255,.95), inset 0 -4px 8px rgba(110,80,160,.16); }
  .bzw { background: linear-gradient(180deg, #fff6ef, #ffe4d4 60%, #fbd3bf);
    box-shadow: 0 26px 44px -20px rgba(190,90,50,.4), 0 8px 16px -8px rgba(190,90,50,.26),
      inset 0 2px 1px rgba(255,255,255,.95), inset 0 -4px 8px rgba(180,90,50,.14);
