  .track { position: absolute; left: 30px; top: 45px; width: 300px; height: 130px; border-radius: 65px;
    background-color: #c3b0e6;
    background-image:
      radial-gradient(120% 140% at 50% 120%, rgba(90,60,140,.18), transparent 55%),
      radial-gradient(90% 70% at 50% -10%, rgba(255,255,255,.45), transparent 60%);
    box-shadow:
      inset 0 10px 18px rgba(80,50,130,.28), inset 0 -6px 12px rgba(255,255,255,.55),
      inset 0 6px 9px rgba(60,30,100,.22), inset 0 0 0 1.5px rgba(90,60,140,.18); }
  .shadow { position: absolute; left: 0; top: ${CY + 46}px; width: 100px; height: 18px; margin-left: -50px; border-radius: 50%;
