  .body { position: absolute; inset: 0; border-radius: 50% 50% 46% 46% / 54% 54% 46% 46%;
    background:
      radial-gradient(40% 30% at 34% 24%, rgba(255,255,255,.95), rgba(255,255,255,0) 70%),
      radial-gradient(80% 70% at 50% 110%, rgba(190,150,200,.45), transparent 60%),
