    background: radial-gradient(70% 70% at 45% 35%, #fffaf6, #f1e2ea 60%, #e2cfdf);
    box-shadow: inset -3px -4px 6px rgba(170,130,180,.35), 0 3px 5px -2px rgba(90,60,120,.3); }
  .arm.l { left: -28px; transform-origin: 100% 50%; }
