  .eye-c, .eye-sq, .mouth-s, .lidline { fill: none; stroke: #3b2c44; stroke-width: 2.6; stroke-linecap: round; stroke-linejoin: round; }
  .lidline { stroke-width: 2.4; }
  .eye ellipse { fill: #3b2c44; }
  .eye { transform-origin: 50% 100%; }
  .cheek { fill: #ff8fa6; filter: blur(1.4px); }
  .mouth-o { fill: #6b2f45; }
  .tear { fill: #9fd6ff; stroke: #fff; stroke-width: .8; }
