</style>
<div class="bg-dawn"></div>
<div class="bg-warm"></div>
<div class="bz" data-hit></div><div class="bzw" data-hit></div>
<div class="track" data-hit></div>
<div class="shadow"></div>
${[0, 1, 2, 3].map(() => '<span class="zz">z</span>').join('')}
