  }

  setup() {
    this.el = {
      blob: this.$('.blob'), shadow: this.$('.shadow'), look: this.$('.look'),
      eyeL: this.$('.eye.l'), eyeR: this.$('.eye.r'), cL: this.$('.eye-c.l'), cR: this.$('.eye-c.r'),
      lidL: this.$('.lidline.l'), lidR: this.$('.lidline.r'), sq: this.$$('.eye-sq'),
      cheeks: this.$$('.cheek'), smile: this.$('.mouth-s'), mouthO: this.$('.mouth-o'), tear: this.$('.tear'),
      armL: this.$('.arm.l'), armR: this.$('.arm.r'),
      zz: this.$$('.zz'), sparks: this.$$('.spark'),
      track: this.$('.track'), bzw: this.$('.bzw'), warm: this.$('.bg-warm'), dawn: this.$('.bg-dawn'),
    };
    this.s = 0; this.flow = -1;  // timeline position + direction of the act playing
    this.P = null;              // smoothed pose
    this.tLand = -1e9; this.landX = ON_X;
    this.now = performance.now();
  }

  render(on, instant) {
    this.flow = on ? 1 : -1;
    if (instant) { this.s = on ? 1 : 0; this.P = null; }
  }

  tick(t, dt) {
    this.now = t;
    const prevU = this.s * DUR;
    this.s = clamp(this.s + (this.flow * dt) / DUR);
    const u = this.s * DUR;
    if (this.flow > 0 && prevU < LAND && u >= LAND) { this.tLand = t; this.landX = ON_X; }

    const T = this.flow > 0 ? poseOn(u) : poseOff((1 - this.s) * DUR);

    // settled extras: breathing while asleep, idle blinks while awake
    const asleep = this.s === 0 && this.flow < 0;
    const awake = this.s === 1 && this.flow > 0;
    if (asleep) {
      const br = 0.035 * Math.sin(t / 620);
      T.sx *= 1 + br * 0.6; T.sy *= 1 + br;
    }
    if (awake && t - this.tLand > 1200 && (t % 3400) < 140) T.lidL = T.lidR = Math.abs((t % 3400) - 70) / 70;
    if (awake && t - this.tLand > 260 && t - this.tLand < 400) T.lidL = T.lidR = Math.abs(t - this.tLand - 330) / 70;

    // smooth the pose (so reversing mid-act blends instead of popping)
    if (!this.P) this.P = { ...T };
    const k = 1 - Math.exp(-dt / 55);
    const P = this.P;
    for (const f of FIELDS) P[f] += (T[f] - P[f]) * k;
    // blinks are instant
    if (awake) { P.lidL = T.lidL; P.lidR = T.lidR; }

    // body
    this.el.blob.style.transform = `translate(${P.x.toFixed(2)}px, ${(CY + 56 + P.y).toFixed(2)}px) translateY(-56px) rotate(${P.rot.toFixed(2)}deg) scale(${P.sx.toFixed(4)}, ${P.sy.toFixed(4)})`;
    const lift = clamp(-P.y / 70);
    this.el.shadow.style.transform = `translateX(${P.x.toFixed(2)}px) scale(${(P.sx - lift * 0.45).toFixed(3)}, ${(1 - lift * 0.4).toFixed(3)})`;
    this.el.shadow.style.opacity = (1 - lift * 0.55).toFixed(3);

    // arms: pop out of the sides and reach up
    const a = clamp(P.arms, 0, 1.2);
    this.el.armL.style.transform = `rotate(${lerp(-18, 58, P.armUp).toFixed(1)}deg) scale(${a.toFixed(3)})`;
    this.el.armR.style.transform = `rotate(${lerp(18, -58, P.armUp).toFixed(1)}deg) scale(${a.toFixed(3)})`;

    // eyes: open ellipse (scaled from its bottom = lid), droopy lid line, closed curve, squeezed ><
    const eye = (g, c, line, lid, cx) => {
      const o = clamp(lid, 0, 1.3);
      const open = o > 0.1 && P.squeeze < 0.5;
      g.style.opacity = open ? 1 : 0;
      g.style.transform = `scaleY(${Math.max(o, 0.1).toFixed(3)})`;
      c.style.opacity = !open && P.squeeze < 0.5 ? 1 : 0;
      const top = 50.2 - 12.4 * Math.min(o, 1);
      line.style.opacity = open ? clamp(P.droop * 1.4).toFixed(3) : 0;
      line.setAttribute('transform', `translate(0 ${top.toFixed(2)})`);
    };
    eye(this.el.eyeL, this.el.cL, this.el.lidL, P.lidL);
    eye(this.el.eyeR, this.el.cR, this.el.lidR, P.lidR);
    this.el.sq.forEach((p) => (p.style.opacity = P.squeeze >= 0.5 ? clamp((P.squeeze - 0.4) * 3).toFixed(3) : 0));

    // mouth + cheeks + tear
    const mo = clamp(P.mouthO);
    this.el.mouthO.style.opacity = mo > 0.02 ? 1 : 0;
    this.el.mouthO.style.transform = `translateY(${(mo * 1.5).toFixed(2)}px) scale(${(0.6 + mo * 0.75).toFixed(3)}, ${Math.max(0.01, mo * 1.25).toFixed(3)})`;
    this.el.smile.style.opacity = clamp(P.smile * (1 - mo)).toFixed(3);
    this.el.cheeks.forEach((c) => (c.style.opacity = (clamp(P.cheek) * 0.85).toFixed(3)));
    this.el.tear.style.opacity = clamp(P.tear * 1.3).toFixed(3);
    this.el.tear.style.transform = `translateY(${((1 - P.tear) * 2).toFixed(2)}px) scale(${(0.6 + P.tear * 0.5).toFixed(3)})`;
    this.el.look.style.transform = `translate(${P.lookX.toFixed(2)}px, ${P.lookY.toFixed(2)}px)`;

    // colour: lilac night → pink dawn (middle) → peach morning
    const c = mix3(LILAC, DAWN, PEACH, this.s).map((v) => v | 0);
    this.el.track.style.backgroundColor = `rgb(${c})`;
    this.el.warm.style.opacity = sm(0.5, 1, this.s).toFixed(3);
    this.el.dawn.style.opacity = (Math.sin(Math.PI * this.s) * 0.95 + sm(0.5, 1, this.s) * 0.05).toFixed(3);
    this.el.bzw.style.opacity = sm(0.25, 0.85, this.s).toFixed(3);

    // z z z: loop while asleep; while nodding off at the middle, the very first "z" rises alone
    const v = (1 - this.s) * DUR;
    const firstZ = this.flow < 0 && v > 1120 && v < 1900;
    this.el.zz.forEach((z, i) => {
      if (i === 3) {
        const ph = clamp((v - 1120) / 780);
        const op = firstZ ? Math.sin(Math.PI * ph) : 0;
        z.style.opacity = op.toFixed(3);
        z.style.transform = `translate(${(P.x + 30 + ph * 26).toFixed(1)}px, ${(CY + P.y - 56 - ph * 36).toFixed(1)}px) scale(${(0.7 + ph * 0.6).toFixed(3)}) rotate(${(-12 + ph * 20).toFixed(1)}deg)`;
        return;
      }
      const ph = ((t / 2100) + i / 3) % 1;
      const op = Math.sin(Math.PI * ph) * clamp(P.zz);
      const zx = P.x + 34 + ph * 34 + Math.sin(ph * 6 + i) * 4;
      const zy = CY + P.y - 58 - ph * 40;
      z.style.opacity = op.toFixed(3);
      z.style.transform = `translate(${zx.toFixed(1)}px, ${zy.toFixed(1)}px) scale(${(0.6 + ph * 0.7).toFixed(3)}) rotate(${(-12 + ph * 20).toFixed(1)}deg)`;
    });

    // sparkle burst on the ON landing
    const sp = this.flow > 0 ? (t - this.tLand) / 560 : 2;
    this.el.sparks.forEach((s, i) => {
      if (sp < 0 || sp > 1) { s.style.opacity = 0; return; }
      const ang = -Math.PI * (0.1 + 0.8 * (i / 5)) + (i % 2 ? 0.15 : -0.1);
      const r = 52 + ease.outCubic(sp) * (24 + (i % 3) * 9);
      s.style.opacity = Math.sin(Math.PI * sp).toFixed(3);
      s.style.transform = `translate(${(this.landX + Math.cos(ang) * r).toFixed(1)}px, ${(CY - 4 + Math.sin(ang) * r * 0.85).toFixed(1)}px) rotate(${(sp * 45).toFixed(0)}deg) scale(${(0.5 + Math.sin(Math.PI * sp) * 0.7).toFixed(3)})`;
    });
  }
}

customElements.define('tg-blob', Blob);
